"""Group the props whose structural answer differs from the checker's, with the declared source text.

Usage: python3 -I patterns.py   (reads *.diff.json, writes patterns.json and prints the head)
"""
import json, re, os
from collections import defaultdict, Counter

H = '/Users/gabe/Projects/caliper-fixtures/shrink/'


def render(t, depth=0):
    if not isinstance(t, dict):
        return str(t)
    k = t.get('kind')
    if k == 'stringLiteral':
        return repr(t.get('value'))
    if k in ('string', 'number', 'boolean', 'null', 'undefined', 'void', 'any', 'unknown', 'never', 'reactNode'):
        return k
    if depth > 3:
        return '..' + str(k)
    if k == 'union':
        parts = [render(x, depth + 1) for x in t.get('types', t.get('members', []))]
        return ' | '.join(parts[:4]) + (f' | +{len(parts) - 4}' if len(parts) > 4 else '')
    if k == 'named':
        return t.get('name', '?') + ('<' + ','.join(render(a, depth + 1) for a in t.get('typeArguments', [])) + '>' if t.get('typeArguments') else '')
    if k == 'array':
        return render(t.get('element', t.get('elementType', {})), depth + 1) + '[]'
    if k == 'function':
        return 'fn'
    return k + ':' + json.dumps({a: b for a, b in t.items() if a != 'kind'})[:70]


_cache = {}


def src_text(file, parent, prop):
    if not file or not os.path.exists(file):
        return None
    if file not in _cache:
        _cache[file] = open(file, errors='replace').read()
    s = _cache[file]
    start = 0
    if parent:
        m = re.search(r'(interface|type|class)\s+' + re.escape(parent) + r'\b', s)
        if m:
            start = m.start()
    pat = re.compile(r'(?m)^\s*(?:readonly\s+)?["\']?' + re.escape(prop) + r'["\']?\??\s*:\s*([^;\n]{0,160})')
    m = pat.search(s, start)
    return m.group(1).strip() if m else None


def feature(src, ctype, s=None):
    if src and re.search(r'ConditionalValue|OverridableStringUnion|SxProps', src):
        return 'generic alias'
    if src is None and s is not None:
        raw = json.dumps(s)
        if 'mappedType' in raw or 'in keyof' in raw:
            return 'mapped'
        if 'indexedAccess' in raw:
            return 'indexed access'
        if 'Partial' in raw or 'Omit' in raw or 'Pick' in raw:
            return 'utility type'
        return 'unknown-source'
    if re.search(r'\bextends\b[^;]*\?', src) or ' infer ' in src:
        return 'conditional'
    if re.search(r'\[\s*\w+\s+in\s', src):
        return 'mapped'
    if '`' in src or ctype.get('kind') == 'templateLiteral':
        return 'template literal'
    if re.search(r'\b(Pick|Omit|Partial|Required|Readonly|Record|Exclude|Extract|NonNullable|Parameters|ReturnType|Awaited)\s*<', src):
        return 'utility type'
    if re.search(r'\w\[[\'"\w]', src) and ('[' in src and not src.rstrip().endswith('[]')) and re.search(r'\w+\[\s*(keyof|[\'"]|\w+\s*\])', src):
        return 'indexed access'
    if 'typeof ' in src or 'keyof ' in src:
        return 'typeof/keyof'
    if re.search(r'\b[A-Z]\w*<', src):
        return 'generic alias'
    if re.search(r'\w\(\)|ReturnType', src):
        return 'call return'
    return 'other'


def main():
    out = {}
    for name in ('chakra-only', 'gate-large'):
        r = json.load(open(H + name + '.diff.json'))['rows']
        grp = defaultdict(list)
        for x in r:
            if x['cls'] in ('spelled_differently', 'concrete_different', 'struct_unresolved', 'checker_opaque_struct_concrete'):
                src = src_text(x.get('file'), x.get('parent'), x['p'])
                key = (x['cls'], render(x['s']), render(x['k']))
                grp[key].append(dict(c=x['c'], p=x['p'], src=src, ck=x['k'], s=x['s']))
        out[name] = [dict(cls=k[0], s=k[1], k=k[2], n=len(v), feat=Counter(feature(e['src'], e['ck'], e['s']) for e in v).most_common(1)[0][0],
                          ex=v[:2], feats=dict(Counter(feature(e['src'], e['ck'], e['s']) for e in v))) for k, v in sorted(grp.items(), key=lambda kv: -len(kv[1]))]
        for e in out[name]:
            for x in e['ex']:
                x.pop('ck', None); x.pop('s', None)
    json.dump(out, open(H + 'patterns.json', 'w'), indent=1)
    for name, rows in out.items():
        print('==', name, 'patterns', len(rows))
        for e in rows[:30]:
            print(e['n'], e['cls'], '|', e['feat'], '|', e['s'][:90], '=>', e['k'][:90], '|', e['ex'][0]['c'], e['ex'][0]['p'], '::', (e['ex'][0]['src'] or '')[:80])


